class TestNormalizeTags:
    def test_strings_converted_to_tags(self):
        result = normalize_tags(["Hello", "World"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_deduplicates(self):
        result = normalize_tags(["foo", "FOO", " foo "])
        assert len(result) == 1
        assert result[0].name == "foo"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["beta", "alpha", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

    def test_accepts_tag_objects(self):
        result = normalize_tags([Tag("hello"), Tag("HELLO")])
        assert len(result) == 1

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

    def test_mixed_tags_and_strings(self):
        result = normalize_tags([Tag("abc"), "ABC", "def"])
        assert len(result) == 2
        assert [t.name for t in result] == ["abc", "def"]

"""Tests for tasks_api.service.TaskService."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
from unittest.mock import Mock, patch

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, TaskRepository
from tasks_api.service import TaskNotFoundError, TaskService

FIXED_NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def now():
    return lambda: FIXED_NOW


@pytest.fixture
def repo():
    return InMemoryTaskRepository()


@pytest.fixture
def service(repo, now):
