class TestCreate:
    def test_basic_creation(self, service):
        task = service.create("Buy milk")
        assert task.id == 1
        assert task.title == "Buy milk"
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.created_at == FIXED_NOW
        assert task.tags == []

    def test_title_is_stripped(self, service):
        task = service.create("  hello  ")
        assert task.title == "hello"

    def test_empty_title_raises(self, service):
        with pytest.raises(ValueError, match="must not be empty"):
            service.create("")

    def test_whitespace_only_title_raises(self, service):
        with pytest.raises(ValueError, match="must not be empty"):
            service.create("   ")

    def test_non_string_title_raises(self, service):
        with pytest.raises(ValueError, match="must be a string"):
            service.create(123)  # type: ignore[arg-type]

    def test_title_too_long_raises(self, service):
        with pytest.raises(ValueError, match="200 characters"):
            service.create("x" * 201)

    def test_custom_max_title_length(self, repo, now):
        svc = TaskService(repo, now=now, max_title_length=10)
        with pytest.raises(ValueError, match="10 characters"):
            svc.create("x" * 11)

    def test_invalid_priority_raises(self, service):
        with pytest.raises(ValueError, match="must be a TaskPriority"):
            service.create("T", priority="high")  # type: ignore[arg-type]

    def test_due_at_naive_raises(self, service):
        with pytest.raises(ValueError, match="timezone-aware"):
            service.create("T", due_at=datetime(2025, 1, 1))

    def test_due_at_non_datetime_raises(self, service):
        with pytest.raises(ValueError, match="must be a datetime"):
            service.create("T", due_at="2025-01-01")  # type: ignore[arg-type]

    def test_due_at_converted_to_utc(self, service):
        from datetime import timezone as tz

        eastern = tz(timedelta(hours=-5))
        due = datetime(2025, 7, 1, 12, 0, tzinfo=eastern)
        task = service.create("T", due_at=due)
        assert task.due_at.tzinfo == timezone.utc
        assert task.due_at == due.astimezone(timezone.utc)

    def test_tags_normalized_and_deduplicated(self, service):
        task = service.create("T", tags=["Hello", "hello", "WORLD"])
        assert [t.name for t in task.tags] == ["hello", "world"]

    def test_with_all_options(self, service):
        due = datetime(2025, 7, 1, tzinfo=timezone.utc)
        task = service.create(
            "Full task",
            priority=TaskPriority.HIGH,
            due_at=due,
            tags=["urgent"],
        )
        assert task.priority == TaskPriority.HIGH
        assert task.due_at == due
        assert task.tags[0].name == "urgent"

    def test_increments_ids(self, service):
        t1 = service.create("A")
        t2 = service.create("B")
        assert t2.id == t1.id + 1

    def test_calls_repository(self, mock_repo, now):
        mock_repo.next_id.return_value = 42
        svc = TaskService(mock_repo, now=now)
        svc.create("Task")
        mock_repo.add.assert_called_once()
        added_task = mock_repo.add.call_args[0][0]
        assert added_task.id == 42


